/** Recorte do balão: a onda de voz (2 barras) e as linhas de texto (3). */
function Recorte({ id }: { id: string }) {
  return (
    <mask id={id} maskUnits="userSpaceOnUse" x="0" y="0" width="64" height="64">
      <rect width="64" height="64" fill="#fff" />
      <g fill="#000">
        <rect className="logo-onda" x="17" y="24" width="4" height="10" rx="2" />
        <rect className="logo-onda" x="23.5" y="19" width="4" height="20" rx="2" />
        <rect className="logo-linha" x="31" y="21" width="20" height="4" rx="2" />
        <rect className="logo-linha" x="31" y="27" width="15" height="4" rx="2" />
        <rect className="logo-linha" x="31" y="33" width="9" height="4" rx="2" />
      </g>
    </mask>
  );
}

function Formas({ mascara }: { mascara: string }) {
  return (
    <g className="logo-balao" mask={`url(#${mascara})`} fill="var(--rosa)">
      <circle cx="34" cy="29" r="24" />
      <path d="M15 41L7 58L29 51Z" />
    </g>
  );
}

const useMascara = () => `prosa-recorte-${useId().replace(/[^a-zA-Z0-9]/g, "")}`;

/** Logotipo completo ("prosa"), usado no cabeçalho. */
export default function Logo() {
  const mascara = useMascara();
  return (
    <svg className="logo" viewBox="-8.0 -85.4 403.8 126.4" role="img" aria-label="prosa">
      <defs>
        <Recorte id={mascara} />
      </defs>
      <path fill="var(--grafite)" d={LETRAS} />
      <g transform="translate(133.72 -85.65) scale(1.65)">
        <Formas mascara={mascara} />
      </g>
    </svg>
  );
}

/**
 * Só o balão (o ícone). "modo" decide quando ele fala:
 * - "hover": só com o mouse em cima;
 * - "as-vezes": dá uma falada a cada poucos segundos, e a animação completa no hover;
 * - "sempre": fala sem parar (tela de carregamento).
 */
export function Balao({ modo = "hover", tamanho = 64 }: { modo?: "hover" | "as-vezes" | "sempre"; tamanho?: number }) {
  const mascara = useMascara();
  return (
    <svg className={`balao balao-${modo}`} viewBox="0 0 64 64" width={tamanho} height={tamanho} aria-hidden>
      <defs>
        <Recorte id={mascara} />
      </defs>
      <Formas mascara={mascara} />
    </svg>
  );
}
